'use strict';

const fs = require('fs');
const path = require('path');

const ENDPOINT = 'http://127.0.0.1:59586/status';
const OUTPUT_DIR = path.join(__dirname, 'results');
const OUTPUT_FILE = path.join(OUTPUT_DIR, 'status.json');

async function main() {
  const response = await fetch(ENDPOINT);

  if (!response.ok) {
    throw new Error(`Request to ${ENDPOINT} failed: HTTP ${response.status}`);
  }

  const body = await response.json();

  if (body.status !== 200) {
    throw new Error(`Unexpected status in response: ${JSON.stringify(body)}`);
  }

  fs.mkdirSync(OUTPUT_DIR, { recursive: true });
  fs.writeFileSync(OUTPUT_FILE, `${JSON.stringify(body, null, 2)}\n`, 'utf8');

  console.log(`Wrote ${OUTPUT_FILE}`);
}

main().catch((error) => {
  console.error(error.message);
  process.exitCode = 1;
});

